namespace Xenvious.Translation
{
    public class Translator<TKey, TValue> : Dictionary<TKey, TValue>, INotifyPropertyChanged
    {
        TValue _default;
        public TValue DefaultValue
        {
            get { return _default; }
            set { _default = value; }
        }

        public Translator() : base()
        {
        }
        public Translator(TValue defaultValue) : base()
        {
            _default = defaultValue;
        }

#pragma warning disable CS0108
        public TValue this[TKey index]
#pragma warning restore CS0108
        {
            [DebuggerNonUserCode]
            get
            {
                if (TryGetValue(index, out var value))
                {
                    return value;
                }

                if (Debugger.IsAttached)
                {
                    Log.Debug($"[Translator] Missing key '{index}' - falling back to binding fallback.");
                }

                throw new KeyNotFoundException(index?.ToString());
            }

            set
            {
                if (TryGetValue(index, out var existing) && EqualityComparer<TValue>.Default.Equals(existing, value))
                {
                    return;
                }

                base[index] = value;
                OnPropertyChanged();
            }
        }

        public event PropertyChangedEventHandler PropertyChanged;

        protected virtual void OnPropertyChanged()
        {
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(Binding.IndexerName));
        }

        public new void Add(TKey key, TValue value)
        {
            base.Add(key, value);
            OnPropertyChanged();
        }

        public new bool Remove(TKey key)
        {
            var removed = base.Remove(key);
            if (removed)
            {
                OnPropertyChanged();
            }

            return removed;
        }

        public new void Clear()
        {
            if (Count == 0)
            {
                return;
            }

            base.Clear();
            OnPropertyChanged();
        }

        public void ReplaceWith(IEnumerable<KeyValuePair<TKey, TValue>> items)
        {
            if (items == null) throw new ArgumentNullException(nameof(items));

            var incoming = new Dictionary<TKey, TValue>();
            foreach (var kvp in items)
            {
                incoming[kvp.Key] = kvp.Value;
            }

            var keysToRemove = Keys.Where(k => !incoming.ContainsKey(k)).ToList();
            var hasChanges = keysToRemove.Count > 0;

            foreach (var key in keysToRemove)
            {
                base.Remove(key);
            }

            foreach (var kvp in incoming)
            {
                if (TryGetValue(kvp.Key, out var existing) && EqualityComparer<TValue>.Default.Equals(existing, kvp.Value))
                {
                    continue;
                }

                base[kvp.Key] = kvp.Value;
                hasChanges = true;
            }

            if (hasChanges)
            {
                OnPropertyChanged();
            }
        }
    }


