            { "zt_name_0", "Peds and vehicles" },
            { "zt_desc_0", "No pedestrians and no traffic in the zone." },
            { "zt_name_1", "Peds" },
            { "zt_desc_1", "No pedestrians in the zone." },
            { "zt_name_2", "Vehicles" },
            { "zt_desc_2", "No traffic in the zone." },
            { "zt_name_3", "Clear players" },
            { "zt_desc_3", "Clears players out of the zone. Rockstar's label for it is \"Contact Mission Area\"." },
            { "zt_name_4", "Peds, vehicles and personal vehicles" },
            { "zt_desc_4", "Like type 0, and personal vehicles are removed too." },
            { "zt_name_5", "No cover" },
            { "zt_desc_5", "Players and NPCs cannot take cover in the zone." },
            { "zt_name_6", "Rocket fire" },
            { "zt_desc_6", "Rockets are fired at players in the zone." },
            { "zt_name_7", "Block GPS" },
            { "zt_desc_7", "The GPS plans no route through the zone." },
            { "zt_name_8", "No player spawning" },
            { "zt_desc_8", "Players do not respawn inside the zone." },
            { "zt_name_9", "Calm water" },
            { "zt_desc_9", "Calms the water in the zone. Value 1 calms the water, value 2 the waves (0 to 1 each). At most 8 per job." },
            { "zt_name_10", "Explosion area" },
            { "zt_desc_10", "Area for explosions. Value 1 is the threshold (0.1 to 1000)." },
            { "zt_name_11", "Menu clear" },
            { "zt_desc_11", "Rockstar's internal type MENU_CLEAR; not offered in the creator." },
            { "zt_name_12", "No emergency services" },
            { "zt_desc_12", "Police, army and other emergency services do not spawn in the zone." },
            { "zt_name_13", "Force object" },
            { "zt_desc_13", "Rockstar's type FORCE_OBJECT; what it does in a job is not checked yet." },
            { "zt_name_14", "No wanted level" },
            { "zt_desc_14", "No wanted level in the zone." },
            { "zt_name_15", "Bomber arena" },
            { "zt_desc_15", "Arena area for bomber modes." },
            { "zt_name_16", "No jumping and climbing" },
            { "zt_desc_16", "Players cannot jump or climb in the zone." },
            { "zt_name_17", "No running" },
            { "zt_desc_17", "Players cannot run in the zone. Value 1 is the move speed (0.1 to 4)." },
            { "zt_name_18", "No weapons" },
            { "zt_desc_18", "Players cannot use weapons in the zone." },
            { "zt_name_19", "Open parachute" },
            { "zt_desc_19", "Opens the parachute in free fall." },
            { "zt_name_20", "Spawn protection" },
            { "zt_desc_20", "Protects the spawn area of a team. Value 1 is the team (1 to 4)." },
            { "zt_name_21", "Show player on map" },
            { "zt_desc_21", "Players in the zone are shown on the map." },
            { "zt_name_22", "Alert NPCs" },
            { "zt_desc_22", "NPCs are alerted when a player enters the zone." },
            { "zt_name_23", "Air drag" },
            { "zt_desc_23", "Changes the air drag of the player's vehicle. Value 1 is the factor (0.5 to 15, 1 is normal)." },
            { "zt_name_24", "Can't leave vehicle" },
            { "zt_desc_24", "Players cannot get out of their vehicle in the zone." },
            { "zt_name_25", "Object respawn" },
            { "zt_desc_25", "Objects respawn in this zone." },
            { "zt_name_26", "Refill special ability" },
            { "zt_desc_26", "Refills the special ability, for example the rocket boost." },
            { "zt_name_27", "Object respawn inside" },
            { "zt_desc_27", "Objects respawn at a point inside this zone." },
            { "zt_name_28", "No VTOL switch" },
            { "zt_desc_28", "VTOL aircraft cannot switch their mode in the zone." },
            { "zt_name_29", "Road switch" },
            { "zt_desc_29", "Switches the roads in the zone (Rockstar: ACTIVATE_ROADS)." },
            { "zt_name_30", "No parachute" },
            { "zt_desc_30", "The parachute cannot be opened in the zone." },
            { "zt_name_31", "No electrocution" },
            { "zt_desc_31", "Players cannot be electrocuted in the zone." },
            { "zt_name_32", "Can't drive" },
            { "zt_desc_32", "Players cannot drive vehicles in the zone." },
            { "zt_name_33", "Speed limit" },
            { "zt_desc_33", "Limits the speed of the player's vehicle. Value 1 is the top speed (1 to 100)." },
            { "zt_name_34", "No control" },
            { "zt_desc_34", "Players lose control in the zone." },
            { "zt_name_35", "Kill zone" },
            { "zt_desc_35", "Players who enter the zone die." },
            { "zt_name_36", "Goal area" },
            { "zt_desc_36", "Goal for a team; the creator sets the team and the points." },
            { "zt_name_37", "Pit stop" },
            { "zt_desc_37", "Pit area of a race: repairs the vehicle. Value 1: 5 to 150, value 2: 0.1 to 15." },
            { "zt_name_38", "Stunt score" },
            { "zt_desc_38", "Stunts in the zone give points." },
            { "zt_name_39", "Return object" },
            { "zt_desc_39", "Objects that get into the zone go back to their start position." },
            { "zt_name_40", "Explode player" },
            { "zt_desc_40", "The player explodes after the set time in the zone. Value 1 is the time in seconds (1 to 20)." },
            { "zt_name_41", "Search area" },
            { "zt_desc_41", "Objects in the zone are hidden until they are found." },
            { "zt_name_42", "Blank" },
            { "zt_desc_42", "Does nothing." },
            { "zt_name_43", "Aggro NPCs" },
            { "zt_desc_43", "NPCs in the zone turn hostile when a player comes in." },
            { "zt_name_44", "Block NPC paths" },
            { "zt_desc_44", "NPCs do not walk through the zone." },
            { "zt_name_45", "Health drain" },
            { "zt_desc_45", "Players lose health in the zone. Value 1 is the amount (1 to 100)." },
            { "zt_name_46", "Metal detector" },
            { "zt_desc_46", "Carrying weapons into the zone raises an alarm." },
            { "zt_name_47", "Explosion danger area" },
            { "zt_desc_47", "Danger area around explosions a player sets off." },
            { "zt_name_48", "Air defence" },
            { "zt_desc_48", "Air defence shoots at aircraft in the zone. Value 1: up to 1000000, value 2: up to 10000. At most 10 per job." },
            { "zt_name_49", "Objective text" },
            { "zt_desc_49", "Shows a different objective text while a player is in the zone." },
            { "zt_name_50", "Altimeter" },
            { "zt_desc_50", "Shows the altimeter in the zone." },
            { "zt_name_51", "Roads off" },
            { "zt_desc_51", "Switches the roads in the zone off, so no traffic drives into it." },
            { "zt_name_52", "Bounds" },
            { "zt_desc_52", "Play area bounds; only in a special creator mode." },
            { "zt_name_53", "Spook NPCs" },
            { "zt_desc_53", "NPCs in the zone get spooked." },
            { "zt_name_54", "Anti-zone" },
            { "zt_desc_54", "Cancels another zone where both overlap." },
            { "zt_name_55", "Leave vehicle" },
            { "zt_desc_55", "NPCs and players get out of their vehicle in the zone." },
            { "zt_name_56", "Blip zone" },
            { "zt_desc_56", "Shows the zone on the map." },
            { "zt_name_57", "Stay in vehicle" },
            { "zt_desc_57", "NPCs and players cannot get out of their vehicle in the zone." },
            { "zt_name_58", "Sound zone" },
            { "zt_desc_58", "Plays a sound in the zone." },
            { "zt_name_59", "Own spawn points" },
            { "zt_desc_59", "Only the job's own spawn points inside the zone are used." },
            { "zt_name_60", "NPCs flee" },
            { "zt_desc_60", "NPCs flee from the zone." },
            { "zt_name_61", "No climbing" },
            { "zt_desc_61", "Players cannot climb in the zone." },
            { "zt_name_62", "No gang chase spawns" },
            { "zt_desc_62", "Gang chase units do not spawn in the zone." },
            { "zt_name_63", "Drop-off zone" },
            { "zt_desc_63", "Drop-off point of a rule; may be very large." },
            { "zt_name_64", "Door switch" },
            { "zt_desc_64", "Switches the door settings while a player is in the zone." },
            { "zt_name_65", "Wanted at once" },
            { "zt_desc_65", "The wanted level comes at once, without the usual delay." },
            { "zt_name_66", "No dispatch" },
            { "zt_desc_66", "Emergency services are not dispatched to the zone." },
            { "zt_name_67", "Clear entities" },
            { "zt_desc_67", "Removes entities from the zone." },
            { "zt_name_68", "Prerequisite zone" },
            { "zt_desc_68", "Entering the zone completes a prerequisite." },
            { "zt_name_69", "Petrol pool" },
            { "zt_desc_69", "Puts a pool of petrol in the zone." },
            { "zt_name_70", "Walk style" },
            { "zt_desc_70", "Changes how players walk in the zone. The style is value 3, which Xenvious does not show." },
            { "zt_name_71", "Gang chase flees" },
            { "zt_desc_71", "Gang chase units flee from the zone." },
            { "zt_name_72", "Lose lives" },
            { "zt_desc_72", "Players lose lives in the zone. Value 1: 1 to 120, value 2: 0.5 to 30." },
            { "zt_name_73", "Aggro check" },
            { "zt_desc_73", "Checks the aggro prerequisites while a player is in the zone." },
            { "zt_name_74", "Entity prerequisite zone" },
            { "zt_desc_74", "Bringing the rule's entity into the zone completes a prerequisite." },
            { "zt_name_75", "Keep wanted level" },
            { "zt_desc_75", "Gives a wanted level and keeps it while in the zone. Value 1 is the stars (0 to 5)." },
            { "zt_name_76", "No ladders" },
            { "zt_desc_76", "Players cannot climb ladders in the zone." },
            { "zt_name_77", "Remove parachute" },
            { "zt_desc_77", "Takes the parachute away and blocks it in the zone." },
            { "zt_name_78", "Roads on" },
            { "zt_desc_78", "Switches the roads in the zone on." },
